package Nexotv.iptv.player.diagnosticsimport Nexotv.iptv.player.diagnostics.*import Nexotv.iptv.player.*import java.net.URLimport java.io.IOExceptionprivate const val CLEAR_TEXT_CAUSE_CHAIN_LIMIT = 16private const val CLEAR_TEXT_MESSAGE_SCAN_LIMIT = 2_048private const val CROSS_PROTOCOL_REDIRECT_MESSAGE = "disallowed cross-protocol redirect (https to http)"internal class CleartextHeadersOnHttpException : IOException()private fun matchesCleartextFailure(cause: Throwable): Boolean {    if (cause is CleartextHeadersOnHttpException) return true    val simpleName = try {        cause.javaClass.simpleName    } catch (_: Exception) {        ""    }    if (simpleName == "CleartextNotPermittedException") return true    val message = try {        cause.message.orEmpty().take(CLEAR_TEXT_MESSAGE_SCAN_LIMIT)    } catch (_: Exception) {        ""    }    if (message.isEmpty()) return false    val mentionsCleartext = message.contains("cleartext", ignoreCase = true)    val mentionsBlock = message.contains("not permitted", ignoreCase = true) ||        message.contains("not allowed", ignoreCase = true) ||        message.contains("network security policy", ignoreCase = true)    return (mentionsCleartext && mentionsBlock) ||        message.contains(CROSS_PROTOCOL_REDIRECT_MESSAGE, ignoreCase = true)}internal fun isCleartextBlocked(failure: Throwable): Boolean {    var current: Throwable? = failure    var depth = 0    while (current != null && depth < CLEAR_TEXT_CAUSE_CHAIN_LIMIT) {        if (matchesCleartextFailure(current)) return true        val next = try {            current.cause        } catch (_: Exception) {            null        }        if (next === current) break        current = next        depth++    }    return false}internal fun cleartextErrorMessageResId(failure: Throwable, headersConfigured: Boolean = false): Int? =    if (!isCleartextBlocked(failure)) null    else if (headersConfigured) R.string.cleartext_blocked_with_headers    else R.string.cleartext_blockedinternal fun isTlsError(failure: Throwable): Boolean {    var current: Throwable? = failure    var depth = 0    while (current != null && depth < CLEAR_TEXT_CAUSE_CHAIN_LIMIT) {        val name = try {            current.javaClass.simpleName        } catch (_: Exception) {            ""        }        val message = try {            current.message.orEmpty().take(CLEAR_TEXT_MESSAGE_SCAN_LIMIT)        } catch (_: Exception) {            ""        }        if (name.contains("ssl", ignoreCase = true) ||            name.contains("certificate", ignoreCase = true) ||            name.contains("certpath", ignoreCase = true) ||            name.contains("handshake", ignoreCase = true) ||            message.contains("ssl", ignoreCase = true) ||            message.contains("certificate", ignoreCase = true) ||            message.contains("certpath", ignoreCase = true) ||            message.contains("handshake", ignoreCase = true) ||            (message.contains("verify", ignoreCase = true) && message.contains("chain", ignoreCase = true))) {            return true        }        val next = try {            current.cause        } catch (_: Exception) {            null        }        if (next === current) break        current = next        depth++    }    return false}internal fun tlsErrorMessageResId(failure: Throwable): Int? =    if (isTlsError(failure)) R.string.tls_cert_or_clock_error    else nullinternal fun isCleartextUrl(url: String): Boolean {    val trimmed = url.trim()    if (trimmed.isEmpty()) return false    return try {        URL(trimmed).protocol.equals("http", ignoreCase = true)    } catch (_: Exception) {        false    }}